dynamic dataOf(dynamic response) => response is Map && response['data'] != null ? response['data'] : response;
List<Map<String, dynamic>> mapsOf(dynamic response) => (dataOf(response) is List ? dataOf(response) as List : const []).whereType<Map>().map((e) => e.cast<String, dynamic>()).toList();
void showError(BuildContext context, Object error) => ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(error is ApiException ? error.message : error.toString())));
String prettyStatus(String value) => value.replaceAll('_', ' ').split(' ').map((v) => v.isEmpty ? v : '${v[0].toUpperCase()}${v.substring(1)}').join(' ');

