class ReadingPlanDetail extends StatefulWidget { const ReadingPlanDetail({required this.api, required this.plan, super.key}); final ApiClient api; final ReadingPlan plan; @override State<ReadingPlanDetail> createState() => _PlanDetailState(); }
class _PlanDetailState extends State<ReadingPlanDetail> { bool busy = false; int? enrollmentId; final completed = <int>{};
  Future<void> enroll() async { setState(() => busy = true); try { final r = await widget.api.request('/reading-plans/${widget.plan.id}/enrollments', method: 'POST', auth: true); final d = dataOf(r); if (d is Map) { enrollmentId = d['id'] as int?; completed.addAll((d['completed_day_ids'] as List? ?? const []).whereType<int>()); } } on ApiException catch (e) { showError(context, e); } finally { if (mounted) setState(() => busy = false); } }
  Future<void> toggle(Map<String, dynamic> day, bool value) async { if (enrollmentId == null) await enroll(); if (enrollmentId == null) return; final dayId = day['id'] as int?; if (dayId == null) return; try { await widget.api.request('/reading-plan-enrollments/$enrollmentId/days/$dayId', method: 'PUT', auth: true, body: {'completed': value}); setState(() { if (value) completed.add(dayId); else completed.remove(dayId); }); } on ApiException catch (e) { showError(context, e); } }
  @override Widget build(BuildContext context) => PageFrame(title: widget.plan.title, child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(widget.plan.description), const SizedBox(height: 18), FilledButton(onPressed: busy ? null : enroll, child: Text(enrollmentId == null ? 'Start this plan' : 'Plan started')), const SizedBox(height: 18), ...widget.plan.days.whereType<Map>().map((day) { final d = day.cast<String, dynamic>(); final id = d['id'] as int?; return CardTile(child: CheckboxListTile(value: id != null && completed.contains(id), onChanged: id == null ? null : (v) => toggle(d, v ?? false), title: Text('Day ${d['day_number'] ?? ''}: ${d['title'] ?? ''}'), subtitle: Text('${d['scripture_reference'] ?? ''}\n${d['scripture_text'] ?? ''}'))); })])); }
}

