class _PasswordChangeState extends State<PasswordChangeScreen> { final form = GlobalKey<FormState>(); final current = TextEditingController(), next = TextEditingController(), confirmation = TextEditingController(); bool busy = false; @override void dispose() { current.dispose(); next.dispose(); confirmation.dispose(); super.dispose(); } Future<void> save() async { if (!(form.currentState?.validate() ?? false)) return; setState(() => busy = true); try { await widget.auth.changePassword(current.text, next.text, confirmation.text); if (mounted) { ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Password updated'))); Navigator.pop(context); } } on ApiException catch (e) { if (mounted) showError(context, e); } finally { if (mounted) setState(() => busy = false); } } @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Change password')), body: Form(key: form, child: ListView(padding: const EdgeInsets.all(20), children: [const Text('Keep your LUMA account secure.', style: TextStyle(fontSize: 24, fontWeight: FontWeight.w700)), const SizedBox(height: 22), field(current, 'Current password'), field(next, 'New password'), field(confirmation, 'Confirm new password'), const SizedBox(height: 12), FilledButton(onPressed: busy ? null : save, child: Text(busy ? 'Updating…' : 'Update password'))])); } Widget field(TextEditingController c, String label) => Padding(padding: const EdgeInsets.only(bottom: 14), child: TextFormField(controller: c, obscureText: true, validator: (v) { if (v == null || v.isEmpty) return 'Enter your ${label.toLowerCase()}'; if (label == 'Confirm new password' && v != next.text) return 'Passwords do not match'; if (label == 'New password' && v.length < 8) return 'Use at least 8 characters'; return null; }, decoration: InputDecoration(labelText: label))); }
